const fasesHistoricas = [
 {id:'origens',number:'I',name:'Origens e antecedentes',range:'476–843'},
 {id:'expansao',number:'II',name:'Formação e expansão',range:'Séculos IX–XIII'},
 {id:'crises',number:'III',name:'Crises e resistências',range:'Séculos XIV–XV'},
 {id:'transformacoes',number:'IV',name:'Transformações',range:'Séculos XV–XVI'}
];
const timelineScreen = document.querySelector('.timeline-screen');
function timelineMarkup(){
 return `<div class="timeline-intro"><p class="eyebrow">CAPÍTULO III · O FEUDALISMO NO TEMPO</p><h2 class="society-title" id="timeline-title" tabindex="-1">Uma história de transformações</h2><p class="modal-text">O feudalismo se formou e se transformou ao longo de séculos. Explore os principais marcos e descubra como eles se relacionam com o mundo do feudo.</p><div class="timeline-reading"><strong>Como ler esta linha</strong><p>Datas indicam acontecimentos; séculos e intervalos também representam processos. Os cartões seguem uma sequência histórica, sem escala proporcional de tempo. Alguns períodos se sobrepõem.</p></div></div>` + fasesHistoricas.map(phase=>`<section class="timeline-phase" aria-labelledby="phase-${phase.id}"><div class="phase-heading"><span aria-hidden="true">${phase.number}</span><div><p>${phase.range}</p><h3 id="phase-${phase.id}" tabindex="-1">${phase.name}</h3></div></div><ol class="chronicle-track">${marcosFeudalismo.filter(item=>item.phase===phase.id).map(item=>`<li class="chronicle-entry"><div class="chronicle-date"><span>${item.date}</span></div><article class="chronicle-card"><p class="event-kind">${item.kind}</p><h4>${item.title}</h4><p>${item.text}</p><details><summary>Relação com o feudalismo</summary><p>${item.why}</p></details><a class="event-source" href="${item.url}" target="_blank" rel="noopener noreferrer">Fonte: ${item.source} ↗</a></article></li>`).join('')}</ol></section>`).join('') + `<div class="timeline-conclusion"><span aria-hidden="true">❧</span><h3>Uma data não muda tudo</h3><p>Um acontecimento pode marcar uma mudança, mas não transforma todas as sociedades ao mesmo tempo. Por isso, não devemos dizer que o feudalismo nasceu em 476 ou terminou de uma vez em 1453.</p><button class="next" type="button" data-screen="feudo">Voltar ao mapa do feudo →</button></div>`;
}
document.querySelector('#timeline-content').innerHTML = timelineMarkup();
document.querySelector('.timeline-sidebar').innerHTML = fasesHistoricas.map(phase=>`<button class="place-link" type="button" data-timeline-phase="${phase.id}"><span class="num">${phase.number}</span>${phase.name}<span class="arrow" aria-hidden="true">↓</span></button>`).join('') + '<button class="place-link" type="button" data-screen="feudo">← Voltar ao feudo</button>';
document.querySelectorAll('[data-timeline-phase]').forEach(button=>button.addEventListener('click',()=>{
 const heading=document.querySelector('#phase-'+button.dataset.timelinePhase);heading.focus({preventScroll:true});heading.scrollIntoView({block:'start',behavior:'instant'});
}));
